import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import { useLang, useT } from '../context/LanguageContext.jsx';

const DISCORD_URL = 'https://discord.rustaco.site';
const SERVER_NAME = 'Rustaco.co - Main 2x';

// ─── EDITA AQUÍ LAS REGLAS ─────────────────────────────────────────────────
// Los iconos (icon) se comparten entre idiomas; solo el texto se traduce.
const SECTION_ICONS = ['bi-person-badge', 'bi-shield-shaded', 'bi-chat-dots', 'bi-shop'];

const RULE_SECTIONS = {
  es: [
    {
      section: 'Cuentas y acceso',
      rules: [
        { title: 'Una cuenta por jugador', text: 'Solo puedes jugar con tu cuenta principal de Steam. El uso de cuentas alternativas (alts) para espiar, ocupar slots, falsear estadísticas o sortear sanciones está prohibido y conlleva el ban de todas las cuentas asociadas.' },
        { title: 'Evasión de sanciones', text: 'Intentar evadir un ban mediante VPN, nuevas cuentas o suplantación reinicia y prolonga la sanción de forma permanente. La única vía válida para revisar un ban es la apelación por ticket.' },
        { title: 'Historial de bans del juego', text: 'No se permite el acceso a cuentas con un VAC o Game Ban de Rust de antigüedad inferior a 365 días. Convivir, compartir base o aliarse con un jugador baneado del servidor también es sancionable.' },
        { title: 'Cuenta verificable', text: 'El staff puede solicitar que tu perfil de Steam sea público durante una investigación. Negarse a colaborar con una investigación activa puede derivar en restricción temporal.' },
      ],
    },
    {
      section: 'Trampas y software de terceros',
      rules: [
        { title: 'Cero tolerancia a las trampas', text: 'Cualquier software que otorgue ventaja injusta —aimbot, ESP/wallhack, spinbot, no-recoil, radar— resulta en ban permanente e irrevocable a la primera infracción, sin excepciones.' },
        { title: 'Scripts y macros', text: 'Están prohibidos los scripts y macros que automaticen acciones del juego, incluyendo macros de no-recoil, auto-farm, auto-clicker y combinaciones de teclas que ejecuten múltiples acciones con una sola pulsación.' },
        { title: 'Abuso de bugs y exploits', text: 'Aprovechar fallos del juego o de los plugins para obtener ventaja (duplicación de objetos, atravesar paredes, stacks ilegales, exploits de terreno) está prohibido. Reportar un exploit en lugar de abusarlo puede ser recompensado.' },
      ],
    },
    {
      section: 'Conducta y comunicación',
      rules: [
        { title: 'Respeto mínimo', text: 'El pique y la rivalidad propios del juego son parte de Rust. Lo que no se tolera es el acoso dirigido y sostenido, el discurso de odio (racismo, xenofobia, homofobia) ni los insultos discriminatorios en chat de voz o texto.' },
        { title: 'Doxxing y amenazas', text: 'Compartir información personal de otro jugador sin su consentimiento, así como amenazas reales (a la integridad física, DDoS, swatting), conlleva ban permanente y puede ser reportado a las autoridades.' },
        { title: 'Spam y publicidad', text: 'No se permite el spam en el chat ni la publicidad de otros servidores, comunidades o servicios ajenos a Rustaco, tanto en el juego como en Discord.' },
      ],
    },
    {
      section: 'Economía, tienda y staff',
      rules: [
        { title: 'Compras y contracargos', text: 'Iniciar un contracargo (chargeback) o disputa sobre una compra de la tienda resulta en ban permanente. Cualquier problema con un pago debe resolverse mediante un ticket de soporte.' },
        { title: 'Suplantación de staff', text: 'Hacerse pasar por miembro del staff, administrador o moderador para engañar a otros jugadores es una falta grave sancionada con ban permanente.' },
        { title: 'Decisiones del staff', text: 'Las decisiones del staff son definitivas dentro del juego. Si consideras que una sanción fue un error, no discutas en el chat: abre un ticket de apelación con tu evidencia y será revisado.' },
      ],
    },
  ],
  en: [
    {
      section: 'Accounts and access',
      rules: [
        { title: 'One account per player', text: 'You may only play on your main Steam account. Using alternate accounts (alts) to spy, take up slots, fake stats or dodge sanctions is prohibited and results in a ban of all associated accounts.' },
        { title: 'Ban evasion', text: 'Attempting to evade a ban via VPN, new accounts or impersonation resets and permanently extends the sanction. The only valid way to review a ban is a ticket appeal.' },
        { title: 'Game ban history', text: 'Accounts with a Rust VAC or Game Ban newer than 365 days are not allowed. Living with, sharing a base with, or allying with a banned player of the server is also punishable.' },
        { title: 'Verifiable account', text: 'Staff may ask you to make your Steam profile public during an investigation. Refusing to cooperate with an active investigation may lead to a temporary restriction.' },
      ],
    },
    {
      section: 'Cheats and third-party software',
      rules: [
        { title: 'Zero tolerance for cheating', text: 'Any software granting an unfair advantage —aimbot, ESP/wallhack, spinbot, no-recoil, radar— results in a permanent, irrevocable ban on the first offense, no exceptions.' },
        { title: 'Scripts and macros', text: 'Scripts and macros that automate in-game actions are prohibited, including no-recoil macros, auto-farm, auto-clicker and key combinations that trigger multiple actions from a single press.' },
        { title: 'Bug and exploit abuse', text: 'Abusing game or plugin bugs for an advantage (item duplication, clipping through walls, illegal stacks, terrain exploits) is prohibited. Reporting an exploit instead of abusing it may be rewarded.' },
      ],
    },
    {
      section: 'Conduct and communication',
      rules: [
        { title: 'Basic respect', text: "Trash talk and rivalry are part of Rust. What is not tolerated is targeted, sustained harassment, hate speech (racism, xenophobia, homophobia) or discriminatory insults in voice or text chat." },
        { title: 'Doxxing and threats', text: "Sharing another player's personal information without consent, as well as real threats (physical harm, DDoS, swatting), results in a permanent ban and may be reported to the authorities." },
        { title: 'Spam and advertising', text: 'Chat spam and advertising other servers, communities or services outside Rustaco is not allowed, both in-game and on Discord.' },
      ],
    },
    {
      section: 'Economy, store and staff',
      rules: [
        { title: 'Purchases and chargebacks', text: 'Filing a chargeback or dispute over a store purchase results in a permanent ban. Any payment issue must be resolved through a support ticket.' },
        { title: 'Staff impersonation', text: 'Impersonating a staff member, administrator or moderator to deceive other players is a serious offense punished with a permanent ban.' },
        { title: 'Staff decisions', text: "Staff decisions are final in-game. If you believe a sanction was a mistake, don't argue in chat: open an appeal ticket with your evidence and it will be reviewed." },
      ],
    },
  ],
  pt: [
    {
      section: 'Contas e acesso',
      rules: [
        { title: 'Uma conta por jogador', text: 'Você só pode jogar com sua conta principal da Steam. O uso de contas alternativas (alts) para espionar, ocupar slots, falsear estatísticas ou burlar punições é proibido e resulta no ban de todas as contas associadas.' },
        { title: 'Evasão de punições', text: 'Tentar evadir um ban via VPN, novas contas ou suplantação reinicia e prolonga a punição de forma permanente. A única via válida para revisar um ban é a apelação por ticket.' },
        { title: 'Histórico de bans do jogo', text: 'Não é permitido o acesso a contas com um VAC ou Game Ban de Rust com menos de 365 dias. Conviver, compartilhar base ou se aliar a um jogador banido do servidor também é punível.' },
        { title: 'Conta verificável', text: 'O staff pode solicitar que seu perfil da Steam seja público durante uma investigação. Recusar-se a colaborar com uma investigação ativa pode resultar em restrição temporária.' },
      ],
    },
    {
      section: 'Cheats e software de terceiros',
      rules: [
        { title: 'Tolerância zero a cheats', text: 'Qualquer software que conceda vantagem injusta —aimbot, ESP/wallhack, spinbot, no-recoil, radar— resulta em ban permanente e irrevogável na primeira infração, sem exceções.' },
        { title: 'Scripts e macros', text: 'São proibidos scripts e macros que automatizem ações do jogo, incluindo macros de no-recoil, auto-farm, auto-clicker e combinações de teclas que executem múltiplas ações com um único toque.' },
        { title: 'Abuso de bugs e exploits', text: 'Aproveitar falhas do jogo ou dos plugins para obter vantagem (duplicação de itens, atravessar paredes, stacks ilegais, exploits de terreno) é proibido. Reportar um exploit em vez de abusar dele pode ser recompensado.' },
      ],
    },
    {
      section: 'Conduta e comunicação',
      rules: [
        { title: 'Respeito mínimo', text: 'A provocação e a rivalidade próprias do jogo fazem parte do Rust. O que não se tolera é o assédio direcionado e contínuo, o discurso de ódio (racismo, xenofobia, homofobia) nem insultos discriminatórios no chat de voz ou texto.' },
        { title: 'Doxxing e ameaças', text: 'Compartilhar informações pessoais de outro jogador sem consentimento, assim como ameaças reais (à integridade física, DDoS, swatting), resulta em ban permanente e pode ser reportado às autoridades.' },
        { title: 'Spam e publicidade', text: 'Não é permitido spam no chat nem publicidade de outros servidores, comunidades ou serviços alheios ao Rustaco, tanto no jogo quanto no Discord.' },
      ],
    },
    {
      section: 'Economia, loja e staff',
      rules: [
        { title: 'Compras e chargebacks', text: 'Iniciar um chargeback ou disputa sobre uma compra da loja resulta em ban permanente. Qualquer problema com um pagamento deve ser resolvido por meio de um ticket de suporte.' },
        { title: 'Suplantação de staff', text: 'Passar-se por membro do staff, administrador ou moderador para enganar outros jogadores é uma falta grave punida com ban permanente.' },
        { title: 'Decisões do staff', text: 'As decisões do staff são definitivas dentro do jogo. Se você considera que uma punição foi um erro, não discuta no chat: abra um ticket de apelação com sua evidência e será revisado.' },
      ],
    },
  ],
};
// ───────────────────────────────────────────────────────────────────────────

export default function Rules() {
  const { lang } = useLang();
  const t = useT();
  const sections = RULE_SECTIONS[lang] || RULE_SECTIONS.es;

  React.useEffect(() => {
    document.body.classList.add('has-video-bg');
    return () => document.body.classList.remove('has-video-bg');
  }, []);

  let ruleNumber = 0;

  return (
    <div className="rw-page">
      <main className="rw-lb-main">
        <div className="rw-lb-head">
          <span className="rw-section-kicker">{t.rulesKicker}</span>
          <h1>{t.rulesTitle}</h1>
          <p>
            {t.rulesIntroPre} <b>{SERVER_NAME}</b>{t.rulesIntroPost}
          </p>
        </div>

        <div className="rw-rules-content">
          {sections.map((section, sIdx) => (
            <section key={section.section}>
              <div className="rw-rules-sectionhead">
                <i className={`bi ${SECTION_ICONS[sIdx] || 'bi-shield-check'}`} aria-hidden="true" />
                <h2>{section.section}</h2>
              </div>
              <div className="rw-rules-list">
                {section.rules.map((rule) => {
                  ruleNumber += 1;
                  return (
                    <article key={rule.title} className="rw-rule-card">
                      <span className="rw-rule-num">{ruleNumber}</span>
                      <div>
                        <h3>{rule.title}</h3>
                        <p>{rule.text}</p>
                      </div>
                    </article>
                  );
                })}
              </div>
            </section>
          ))}

          <div className="rw-rules-notice">
            <i className="bi bi-exclamation-triangle" aria-hidden="true" />
            <div>
              <strong>{t.rulesNoticeTitle}</strong>
              <p>{t.rulesNoticeText}</p>
              <a
                className="rw-btn rw-btn--discord rw-btn--sm"
                href={DISCORD_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <i className="bi bi-discord" /> {t.rulesAppeal}
              </a>
            </div>
          </div>
        </div>
      </main>

      <footer className="rw-footer">
        <div className="rw-footer-brand">
          <img src={logoNuevo} alt="Rustaco" />
          <span>{t.footerRights}</span>
        </div>
        <nav className="rw-footer-links">
          <Link to="/">{t.navHome}</Link>
          <Link to="/maps">{t.navMaps}</Link>
          <Link to="/events">{t.navLeaderboard}</Link>
          <a href={DISCORD_URL} target="_blank" rel="noopener noreferrer">{t.navDiscord}</a>
        </nav>
      </footer>
    </div>
  );
}
